from pathlib import Path
p=Path('index.html');s=p.read_text()
css='''<style>
html.pelagic-loading{overflow:hidden}.site-loader{position:fixed;inset:0;z-index:20000;display:flex;flex-direction:column;justify-content:space-between;padding:28px 4%;background:#020f17;color:#dcece8;transition:opacity .7s ease,visibility .7s;isolation:isolate}.site-loader::before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(0deg,#020f17dd,#020f1744),url('./loader-poster.jpg') 65% center/cover}.loader-brand{font-size:23px;letter-spacing:.16em}.loader-center{align-self:center;width:min(620px,92%)}.loader-kicker,.loader-footer{font:10px/1.6 'DM Sans',sans-serif;letter-spacing:.18em;text-transform:uppercase}.loader-title{font:700 clamp(72px,12vw,170px)/.85 'Barlow Condensed',Impact,sans-serif;text-transform:uppercase;letter-spacing:-.025em;margin:22px 0 34px}.loader-track{height:1px;background:#dcece833;position:relative}.loader-track span{display:block;height:100%;background:#8fe9ec;width:0;transition:width .3s ease}.loader-meta{display:flex;justify-content:space-between;margin-top:14px;font-size:11px}.loader-footer{display:flex;justify-content:space-between;align-items:center}.loader-skip{border:1px solid #dcece866;background:#020f1755;color:inherit;padding:12px 18px;cursor:pointer;min-height:44px}.site-loader.is-done{opacity:0;visibility:hidden;pointer-events:none}#water-toggle{visibility:hidden}html:not(.pelagic-loading) #water-toggle{visibility:visible}@media(prefers-reduced-motion:reduce){.site-loader,.loader-track span{transition:none}}
</style><script>document.documentElement.classList.add('pelagic-loading')</script>'''
loader='''<div class="site-loader" id="site-loader" role="status" aria-label="Loading PELAGIC"><div class="loader-brand">PELAGIC ↗</div><div class="loader-center"><div class="loader-kicker">Preparing the descent</div><div class="loader-title">Beneath<br>the known.</div><div class="loader-track" role="progressbar" aria-label="Site assets" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span></span></div><div class="loader-meta"><span id="loader-status">Loading the expedition</span><span id="loader-count">0 / 0</span></div></div><div class="loader-footer"><span>Three worlds. One descent.</span><button class="loader-skip" type="button">Enter site ↘</button></div></div>'''
js='''<script>(()=>{const loader=document.querySelector('#site-loader'),bar=loader.querySelector('.loader-track'),fill=bar.firstElementChild,status=document.querySelector('#loader-status'),count=document.querySelector('#loader-count');let done=0,failed=0,closed=false;const tasks=[];function track(p){tasks.push(Promise.resolve(p).catch(()=>{failed++}).finally(()=>{done++;count.textContent=done+' / '+tasks.length;bar.setAttribute('aria-valuenow',Math.round(done/tasks.length*100));fill.style.width=(done/tasks.length*100)+'%'}))}function enter(){if(closed)return;closed=true;document.documentElement.classList.remove('pelagic-loading');loader.classList.add('is-done');loader.setAttribute('aria-hidden','true');loader.inert=true;dispatchEvent(new Event('resize'));setTimeout(()=>loader.remove(),800)}loader.querySelector('button').addEventListener('click',enter);for(const v of document.querySelectorAll('video'))track(new Promise((resolve,reject)=>{if(v.readyState>=4){resolve();return}const finish=()=>{cleanup();resolve()},error=()=>{cleanup();reject()},cleanup=()=>{v.removeEventListener('canplaythrough',finish);v.removeEventListener('error',error)};v.addEventListener('canplaythrough',finish,{once:true});v.addEventListener('error',error,{once:true});v.preload='auto';if(v.networkState===0)v.load()}));for(const img of document.images)track(img.decode());track(document.fonts.ready);track(new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=reject;img.src='./loader-poster.jpg'}));count.textContent='0 / '+tasks.length;const timeout=setTimeout(()=>{status.textContent='Some assets are taking longer — you can enter';},15000);Promise.all(tasks).then(()=>{clearTimeout(timeout);status.textContent=failed?'Ready with '+failed+' unavailable assets':'Expedition ready';setTimeout(enter,450)});window.pelagicLoader={get total(){return tasks.length},get loaded(){return done},get failed(){return failed},get closed(){return closed}};})();</script>'''
s=s.replace('</head>',css+'</head>',1).replace('<body>','<body>'+loader,1)
s=s.replace("nav,aside.depth,.stage,.chapter-stage,.intro,.quote,footer,dialog","#site-loader,nav,aside.depth,.stage,.chapter-stage,.intro,.quote,footer,dialog")
s=s.replace('</body>',js+'</body>');p.write_text(s)
